func replaceHomophones(_ text: String) -> String {
    let pattern = try! NSRegularExpression(pattern: "(?i)\\b(\\w+)([\\s._-]?)(\\w+)\\b") // Case insensitive word boundary match
    var mutableText = text
    if let match = pattern.firstMatch(in: text, range: NSRange(text.startIndex..., in: text)) {
        let range = text.index(text.startIndex, offsetBy: match.range.location)..<text.index(text.startIndex, offsetBy: match.range.location + match.range.length)
        let incorrectHomophone = String(text[range])
        guard let correctForm = homophoneDictionary[incorrectHomophone] else { return text }
        mutableText = text.replacingCharacters(in: range, with: correctForm)
    }
    return mutableText
}
