    json j = json::parse(jsonStr);
    std::vector<int> arr = j["array"].get<std::vector<int>>();
    bubbleSort(arr);
    std::cout << "[";
    for (auto it = arr.cbegin(); it != arr.cend(); ++it) {
        std::cout << *it;
        if (it != arr.cend() - 1) std::cout << ", ";
    }
    std::cout << "]";
}
```

